void GameFlowUi::prepareScores() {
    if(scores_)return;auto& session=*data_.session;scores_=std::make_unique<GlueScreen>(session.world()->resources(),data_.assets->decoder(),renderer_,text_,scoreFile,"ScoreScreenFrame");for(auto name:{"ScoreScreen4ColumnFrame","ScoreScreenReplaySavedButton","SaveReplayPanel","ScoreScreenTeamsButton","ScoreScreenTeamsText","ScoreScreenTeamColorBackdrop","ScoreScreenTeamColorButton"})scores_->visible(name,false);FrameDefinitions source;source.load(session.world()->resources(),scoreFile);for(auto name:{"ScoreScreenBackground","ScoreScreenPageTab","ScoreScreenBarTop"}){auto art=source.frame(name).property("BackgroundArt");if(!art.empty())scoreModels_.push_back(art.front());}scores_->focus("ScoreScreenOkButton");
}
const std::vector<std::string>& GameFlowUi::scoreModels() {if(data_.session->exitRequest()!=SessionExit::None && data_.session->showScores())prepareScores();return scoreModels_;}
